/* Applied before paint; preference is device-local and never changes account permissions. */
(()=>{const themes=['midnight','daylight','sunlit','system'];let choice='midnight';try{const saved=localStorage.getItem('maha-theme');if(themes.includes(saved))choice=saved;}catch{}const media=matchMedia('(prefers-color-scheme: dark)');function apply(value){choice=value;document.documentElement.dataset.theme=value==='system'?(media.matches?'midnight':'daylight'):value;document.documentElement.dataset.themeChoice=value;document.documentElement.style.colorScheme=document.documentElement.dataset.theme==='midnight'?'dark':'light';}apply(choice);media.addEventListener('change',()=>{if(choice==='system')apply(choice);});
function init(){const make=(tag,cls,text)=>{const e=document.createElement(tag);if(cls)e.className=cls;if(text)e.textContent=text;return e;};const header=document.querySelector('body>header');if(header?.querySelector('.brand'))document.body.classList.add('studio-shell');
const appearance=make('button','ui-trigger studio-appearance','Appearance');appearance.type='button';appearance.setAttribute('aria-haspopup','dialog');const settings=make('dialog','studio-settings');settings.id='studio-appearance';settings.setAttribute('aria-labelledby','studio-theme-title');appearance.setAttribute('aria-controls',settings.id);const title=make('h2',null,'Appearance');title.id='studio-theme-title';const close=make('button','ui-trigger','Close');close.type='button';close.onclick=()=>settings.close();settings.append(close,title,make('p','ui-panel-note','Choose a theme. Your selection is remembered on this device.'));const group=make('div','studio-theme-options');group.setAttribute('role','group');group.setAttribute('aria-label','Color theme');for(const [value,label,description] of [['midnight','Midnight','Charcoal · ivory · lime'],['daylight','Daylight','White · graphite · blue'],['sunlit','Sunlit','Cream · cocoa · amber'],['system','System','Follow your device']]){const b=make('button','studio-theme-option');b.type='button';b.dataset.choice=value;const swatch=make('span','studio-swatch');swatch.dataset.swatch=value;swatch.setAttribute('aria-hidden','true');b.append(swatch,make('strong',null,label),make('small',null,description));b.onclick=()=>{apply(value);try{localStorage.setItem('maha-theme',value);}catch{}sync();};group.append(b);}function sync(){group.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.choice===choice)));}sync();settings.append(group);document.body.append(settings);(header||document.body).append(appearance);appearance.onclick=()=>settings.showModal();settings.addEventListener('close',()=>appearance.focus());
function menu(label){const d=make('details','studio-menu');const summary=make('summary',null,'•••');summary.setAttribute('aria-label',label);const content=make('div','studio-menu-items');d.append(summary,content);d.addEventListener('click',e=>{if(e.target.closest('button,a'))d.open=false;});return [d,content];}
const album=document.getElementById('album-dialog');if(album){const close=document.getElementById('album-close');close.textContent='✕';close.setAttribute('aria-label','Close album');const top=make('div','studio-album-header'),meta=make('div','studio-album-meta'),art=document.getElementById('album-art'),heading=document.getElementById('album-heading'),artist=document.getElementById('album-artist');top.append(art,meta);meta.append(make('p','eyebrow','ALBUM'),heading,artist);album.prepend(top);const actions=album.querySelector('.album-buttons');meta.append(actions);const [more,items]=menu('More album actions');actions.append(more);const artAdmin=document.getElementById('album-find-art')?.parentElement;if(artAdmin)items.append(artAdmin);const rename=document.getElementById('rename-album');if(rename)items.append(rename);const note=document.getElementById('album-art-note');if(note)meta.append(note);
function organize(){for(const b of [...actions.children]){if(b===more||b.id==='album-play'||b.id==='album-shuffle'||b.hasAttribute('data-album-favorite'))continue;items.append(b);}album.querySelectorAll('#album-tracks>li').forEach((row,index)=>{if(row.dataset.studio)return;row.dataset.studio='1';const number=make('span','studio-track-number',String(index+1));row.prepend(number);const [d,content]=menu('Track '+(index+1)+' actions');for(const child of [...row.children])if(child!==number&&!child.classList.contains('album-track')&&!child.hasAttribute('data-track-favorite'))content.append(child);if(content.children.length)row.append(d);});}organize();new MutationObserver(organize).observe(album,{childList:true,subtree:true});album.addEventListener('close',()=>album.querySelectorAll('details[open]').forEach(d=>d.open=false));}
document.addEventListener('click',e=>document.querySelectorAll('.studio-menu[open]').forEach(d=>{if(!d.contains(e.target))d.open=false;}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){const d=document.activeElement?.closest('.studio-menu[open]');if(d){e.preventDefault();e.stopPropagation();d.open=false;d.querySelector('summary').focus();}}},true);
}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();})();
